export function getAdminHtml() {
  return "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>DotA & Friends - PvPGN Server Admin Portal</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root {\n  --color-paper: #0B0F19;\n  --color-paper-2: #111827;\n  --color-paper-3: #1E293B;\n  --color-rule: rgba(255,255,255,0.08);\n  --color-ink: #F8FAFC;\n  --color-ink-2: #94A3B8;\n  --color-accent: #38BDF8;\n  --color-frost: #7DD3FC;\n  --color-warm: #FBBF24;\n  --color-success: #34D399;\n  --color-danger: #F43F5E;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{\n  background-color:var(--color-paper);\n  background-image:\n    radial-gradient(ellipse 70% 50% at 50% -10%, rgba(56,189,248,0.12), transparent 70%),\n    radial-gradient(ellipse 50% 35% at 90% 20%, rgba(99,102,241,0.08), transparent 60%);\n  background-attachment:fixed;\n  color:var(--color-ink);\n  font-family:'Inter',system-ui,-apple-system,sans-serif;\n  min-height:100vh;\n  padding:1.5rem;\n  line-height:1.5;\n}\n.container{max-width:1440px;margin:0 auto}\n\n/* Header */\nheader{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  padding-bottom:1.5rem;\n  border-bottom:1px solid var(--color-rule);\n  margin-bottom:1.5rem;\n  flex-wrap:wrap;\n  gap:1rem;\n}\n.brand{display:flex;align-items:center;gap:.85rem;flex-wrap:wrap}\n.brand-title{\n  font-family:'Plus Jakarta Sans',sans-serif;\n  font-size:1.5rem;\n  font-weight:800;\n  letter-spacing:-.02em;\n  background:linear-gradient(135deg, #F8FAFC 30%, #7DD3FC 100%);\n  -webkit-background-clip:text;\n  -webkit-text-fill-color:transparent;\n}\n.brand-badge{\n  background:rgba(56,189,248,0.12);\n  color:var(--color-frost);\n  border:1px solid rgba(56,189,248,0.25);\n  font-size:.68rem;\n  font-weight:700;\n  padding:.2rem .65rem;\n  border-radius:9999px;\n  text-transform:uppercase;\n  letter-spacing:.06em;\n}\n.server-pill{\n  display:inline-flex;\n  align-items:center;\n  gap:.4rem;\n  background:#111827;\n  border:1px solid var(--color-rule);\n  padding:.35rem .75rem;\n  border-radius:9999px;\n  font-family:'JetBrains Mono',monospace;\n  font-size:.78rem;\n  color:var(--color-ink-2);\n}\n.pulse-dot{\n  width:8px;\n  height:8px;\n  border-radius:50%;\n  background:var(--color-success);\n  box-shadow:0 0 10px var(--color-success);\n}\n.actions{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}\n\n/* Buttons */\nbutton, .btn{\n  padding:.5rem 1rem;\n  border-radius:.5rem;\n  border:none;\n  font-family:'Plus Jakarta Sans',sans-serif;\n  font-weight:600;\n  font-size:.85rem;\n  cursor:pointer;\n  display:inline-flex;\n  align-items:center;\n  gap:.45rem;\n  text-decoration:none;\n  transition:all .15s ease;\n}\n.btn-primary{\n  background:linear-gradient(135deg, #0284C7, #2563EB);\n  color:#fff;\n  box-shadow:0 4px 14px rgba(37,99,235,0.25);\n}\n.btn-primary:hover{\n  background:linear-gradient(135deg, #0369A1, #1D4ED8);\n  transform:translateY(-1px);\n  box-shadow:0 6px 20px rgba(37,99,235,0.35);\n}\n.btn-success{\n  background:linear-gradient(135deg, #059669, #10B981);\n  color:#fff;\n  box-shadow:0 4px 14px rgba(16,185,129,0.2);\n}\n.btn-success:hover{background:linear-gradient(135deg, #047857, #059669);transform:translateY(-1px)}\n.btn-warning{background:#D97706;color:#fff}\n.btn-warning:hover{background:#B45309}\n.btn-danger{background:#E11D48;color:#fff}\n.btn-danger:hover{background:#BE123C}\n.btn-secondary{\n  background:var(--color-paper-3);\n  color:var(--color-ink);\n  border:1px solid var(--color-rule);\n}\n.btn-secondary:hover{background:#334155;color:#fff}\n.btn-sm{padding:.3rem .65rem;font-size:.78rem}\n\n/* Overview Stat Cards */\n.stats-grid{\n  display:grid;\n  grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));\n  gap:1rem;\n  margin-bottom:1.5rem;\n}\n.stat-card{\n  background:var(--color-paper-2);\n  border:1px solid var(--color-rule);\n  border-radius:1rem;\n  padding:1.25rem;\n  position:relative;\n  overflow:hidden;\n  transition:border-color .2s;\n}\n.stat-card:hover{border-color:rgba(56,189,248,0.3)}\n.stat-card::before{\n  content:'';\n  position:absolute;\n  top:0;left:0;right:0;height:2px;\n  background:linear-gradient(90deg, transparent, rgba(56,189,248,0.4), transparent);\n}\n.stat-label{\n  font-size:.72rem;\n  font-weight:600;\n  color:var(--color-ink-2);\n  text-transform:uppercase;\n  letter-spacing:.06em;\n}\n.stat-value{\n  font-family:'Plus Jakarta Sans',sans-serif;\n  font-size:1.85rem;\n  font-weight:800;\n  color:#fff;\n  margin-top:.35rem;\n  letter-spacing:-.02em;\n}\n.stat-sub{font-size:.78rem;color:var(--color-ink-2);font-weight:500;margin-left:.35rem}\n\n/* Tabs Nav */\n.tabs-nav{\n  display:flex;\n  gap:.35rem;\n  border-bottom:1px solid var(--color-rule);\n  margin-bottom:1.5rem;\n  overflow-x:auto;\n  padding-bottom:.25rem;\n}\n.tab-btn{\n  background:transparent;\n  border:none;\n  color:var(--color-ink-2);\n  padding:.75rem 1.15rem;\n  border-radius:.65rem .65rem 0 0;\n  font-family:'Plus Jakarta Sans',sans-serif;\n  font-size:.875rem;\n  font-weight:600;\n  cursor:pointer;\n  display:flex;\n  align-items:center;\n  gap:.5rem;\n  transition:all .15s;\n  border-bottom:2px solid transparent;\n  white-space:nowrap;\n}\n.tab-btn:hover{color:var(--color-ink);background:rgba(255,255,255,0.02)}\n.tab-btn.active{\n  color:var(--color-frost);\n  border-bottom-color:var(--color-accent);\n  background:rgba(56,189,248,0.06);\n}\n.tab-badge{\n  background:var(--color-paper-3);\n  color:var(--color-ink-2);\n  font-size:.7rem;\n  padding:.15rem .45rem;\n  border-radius:9999px;\n  font-family:'JetBrains Mono',monospace;\n}\n.tab-btn.active .tab-badge{\n  background:rgba(56,189,248,0.2);\n  color:var(--color-frost);\n}\n\n/* Panels */\n.tab-content{display:none}\n.tab-content.active{display:block}\n.wc3-panel{\n  background:var(--color-paper-2);\n  border:1px solid var(--color-rule);\n  border-radius:1rem;\n  padding:1.5rem;\n  margin-bottom:1.5rem;\n}\n.panel-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;flex-wrap:wrap;gap:.75rem}\n.panel-title{\n  font-family:'Plus Jakarta Sans',sans-serif;\n  font-size:1.15rem;\n  font-weight:700;\n  color:var(--color-ink);\n  display:flex;\n  align-items:center;\n  gap:.6rem;\n}\n\n/* Filter pills */\n.filter-tabs{display:flex;gap:.35rem;background:#0d131f;padding:.25rem;border-radius:.5rem;border:1px solid var(--color-rule);flex-wrap:wrap}\n.filter-tab{\n  background:transparent;\n  border:none;\n  color:var(--color-ink-2);\n  padding:.35rem .75rem;\n  border-radius:.35rem;\n  font-size:.78rem;\n  font-weight:600;\n  cursor:pointer;\n  transition:all .15s;\n}\n.filter-tab.active{background:var(--color-paper-3);color:var(--color-frost);border:1px solid rgba(56,189,248,0.2)}\n.filter-tab:hover:not(.active){color:var(--color-ink);background:var(--color-paper-3)}\n\n.search-input{\n  background:var(--color-paper-3);\n  border:1px solid var(--color-rule);\n  border-radius:.5rem;\n  padding:.55rem .95rem;\n  color:var(--color-ink);\n  font-size:.85rem;\n  min-width:260px;\n  transition:border-color .15s;\n}\n.search-input:focus{outline:none;border-color:var(--color-accent);box-shadow:0 0 10px rgba(56,189,248,0.15)}\n\n/* Tables */\n.table-wrap{overflow-x:auto;border-radius:.65rem;border:1px solid var(--color-rule)}\ntable{width:100%;border-collapse:collapse;text-align:left;font-size:.875rem}\nth{\n  background:#141d2e;\n  color:var(--color-ink-2);\n  padding:.85rem 1rem;\n  font-weight:600;\n  font-size:.72rem;\n  text-transform:uppercase;\n  letter-spacing:.05em;\n  border-bottom:1px solid var(--color-rule);\n}\ntd{padding:.85rem 1rem;border-bottom:1px solid var(--color-rule);color:var(--color-ink)}\ntr:hover td{background:rgba(255,255,255,0.02)}\ntr:last-child td{border-bottom:none}\n\n/* Badges */\n.badge{\n  display:inline-flex;\n  align-items:center;\n  gap:.3rem;\n  padding:.2rem .6rem;\n  border-radius:.4rem;\n  font-size:.7rem;\n  font-weight:700;\n  letter-spacing:.04em;\n  text-transform:uppercase;\n}\n.badge-admin{background:rgba(234,179,8,0.12);color:#FDE047;border:1px solid rgba(234,179,8,0.3)}\n.badge-op{background:rgba(6,182,212,0.12);color:#67E8F9;border:1px solid rgba(6,182,212,0.3)}\n.badge-bot{background:rgba(168,85,247,0.15);color:#C084FC;border:1px solid rgba(168,85,247,0.3)}\n.badge-user{background:rgba(255,255,255,0.05);color:var(--color-ink-2);border:1px solid var(--color-rule)}\n.badge-active{background:rgba(16,185,129,0.12);color:#6EE7B7;border:1px solid rgba(16,185,129,0.3)}\n.badge-locked{background:rgba(239,68,68,0.12);color:#FCA5A5;border:1px solid rgba(239,68,68,0.3)}\n.badge-open{background:rgba(56,189,248,0.12);color:#7DD3FC;border:1px solid rgba(56,189,248,0.3)}\n.badge-started{background:rgba(16,185,129,0.12);color:#6EE7B7;border:1px solid rgba(16,185,129,0.3)}\n.badge-gold{background:rgba(251,191,36,0.15);color:#FBBF24;border:1px solid rgba(251,191,36,0.3)}\n.badge-silver{background:rgba(203,213,225,0.15);color:#CBD5E1;border:1px solid rgba(203,213,225,0.3)}\n.badge-bronze{background:rgba(217,119,6,0.15);color:#F59E0B;border:1px solid rgba(217,119,6,0.3)}\n\n.action-btns{display:flex;gap:.35rem;align-items:center;flex-wrap:wrap}\n.action-btn{padding:.3rem .6rem;border-radius:.375rem;font-size:.75rem;font-weight:600;border:none;cursor:pointer}\n.role-select{\n  background:var(--color-paper-3);\n  border:1px solid var(--color-rule);\n  color:var(--color-ink);\n  font-size:.75rem;\n  padding:.35rem .6rem;\n  border-radius:.375rem;\n  cursor:pointer;\n}\n.role-select:focus{outline:none;border-color:var(--color-accent)}\n\n/* Progress Bars for Container Resources */\n.progress-wrap{\n  background:rgba(255,255,255,0.06);\n  border-radius:9999px;\n  height:8px;\n  width:120px;\n  overflow:hidden;\n  display:inline-block;\n  vertical-align:middle;\n  margin-right:.5rem;\n}\n.progress-fill{\n  height:100%;\n  border-radius:9999px;\n  background:linear-gradient(90deg, #38BDF8, #3B82F6);\n  transition:width .3s ease;\n}\n.progress-fill.fill-warn{background:linear-gradient(90deg, #FBBF24, #F59E0B)}\n.progress-fill.fill-danger{background:linear-gradient(90deg, #F43F5E, #E11D48)}\n\n/* Database Banner */\n.db-banner{\n  background:linear-gradient(90deg, rgba(30,58,138,0.35) 0%, rgba(17,24,39,0.85) 100%);\n  border:1px solid rgba(56,189,248,0.25);\n  border-radius:.75rem;\n  padding:1.15rem 1.4rem;\n  margin-bottom:1.5rem;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  flex-wrap:wrap;\n  gap:1rem;\n}\n.copy-chip{\n  background:var(--color-paper-3);\n  border:1px solid var(--color-rule);\n  color:var(--color-frost);\n  font-family:'JetBrains Mono',monospace;\n  padding:.2rem .5rem;\n  border-radius:.4rem;\n  cursor:pointer;\n  font-size:.8rem;\n  transition:all .15s;\n}\n.copy-chip:hover{background:var(--color-accent);color:#0B0F19;border-color:var(--color-accent)}\n\n/* Channel Grid */\n.channel-grid{\n  display:grid;\n  grid-template-columns:repeat(auto-fill, minmax(280px, 1fr));\n  gap:1rem;\n}\n.channel-card{\n  background:var(--color-paper-3);\n  border:1px solid var(--color-rule);\n  border-radius:.75rem;\n  padding:1.15rem;\n  transition:border-color .15s;\n}\n.channel-card:hover{border-color:rgba(56,189,248,0.3)}\n.channel-name{font-weight:700;color:#fff;font-size:.95rem;margin-bottom:.35rem}\n.channel-meta{display:flex;align-items:center;justify-content:space-between;font-size:.78rem;color:var(--color-ink-2)}\n\n/* Log Terminal */\n.log-terminal{\n  background:#050811;\n  border:1px solid var(--color-rule);\n  border-radius:.75rem;\n  padding:1rem;\n  font-family:'JetBrains Mono',monospace;\n  font-size:.78rem;\n  color:#E2E8F0;\n  max-height:550px;\n  overflow-y:auto;\n  line-height:1.6;\n}\n.log-line{padding:.1rem 0;word-break:break-all}\n.log-info{color:#7DD3FC}\n.log-warn{color:#FDE047}\n.log-err{color:#FCA5A5}\n\n/* Form inputs & Textareas */\n.form-group{margin-bottom:1.15rem}\n.form-group label{display:block;font-size:.72rem;font-weight:600;text-transform:uppercase;color:var(--color-ink-2);margin-bottom:.4rem;letter-spacing:.05em}\n.form-control{\n  width:100%;\n  padding:.7rem .95rem;\n  background:var(--color-paper-3);\n  border:1px solid var(--color-rule);\n  border-radius:.55rem;\n  color:#fff;\n  font-size:.9rem;\n}\n.form-control:focus{outline:none;border-color:var(--color-accent);box-shadow:0 0 10px rgba(56,189,248,0.2)}\ntextarea.form-control{font-family:'JetBrains Mono',monospace;font-size:.82rem;line-height:1.5;resize:vertical}\n\n/* Real-time Chat Dialog Window */\n.chat-dialog-container {\n  display: flex;\n  flex-direction: column;\n  background: #060913;\n  border: 1px solid var(--color-rule);\n  border-radius: 1rem;\n  overflow: hidden;\n  height: 620px;\n  box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n  margin-bottom: 1.5rem;\n}\n.chat-dialog-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: .85rem 1.25rem;\n  background: #0d1322;\n  border-bottom: 1px solid var(--color-rule);\n  flex-wrap: wrap;\n  gap: .75rem;\n}\n.chat-dialog-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 1rem 1.25rem;\n  font-family: 'JetBrains Mono', monospace;\n  font-size: .84rem;\n  line-height: 1.6;\n  display: flex;\n  flex-direction: column;\n  gap: .25rem;\n  background: radial-gradient(ellipse at 50% 0%, rgba(56,189,248,0.03), transparent 70%);\n}\n.chat-line {\n  display: flex;\n  align-items: baseline;\n  gap: .5rem;\n  padding: .2rem .5rem;\n  border-radius: .35rem;\n  transition: background .15s;\n}\n.chat-line:hover {\n  background: rgba(255, 255, 255, 0.05);\n}\n.chat-time {\n  font-size: .72rem;\n  color: var(--color-ink-2);\n  white-space: nowrap;\n}\n.chat-badge-channel {\n  background: rgba(56, 189, 248, 0.15);\n  color: var(--color-frost);\n  border: 1px solid rgba(56, 189, 248, 0.3);\n  font-size: .68rem;\n  font-weight: 700;\n  padding: .1rem .45rem;\n  border-radius: .3rem;\n  white-space: nowrap;\n}\n.chat-badge-source {\n  font-size: .65rem;\n  font-weight: 700;\n  padding: .1rem .4rem;\n  border-radius: .3rem;\n  white-space: nowrap;\n}\n.chat-source-web { background: rgba(16, 185, 129, 0.15); color: #6EE7B7; border: 1px solid rgba(16, 185, 129, 0.3); }\n.chat-source-bnet { background: rgba(168, 85, 247, 0.15); color: #C084FC; border: 1px solid rgba(168, 85, 247, 0.3); }\n.chat-user {\n  font-weight: 700;\n  color: #F8FAFC;\n  cursor: pointer;\n  white-space: nowrap;\n}\n.chat-user:hover {\n  color: var(--color-accent);\n  text-decoration: underline;\n}\n.chat-msg-text {\n  color: #E2E8F0;\n  word-break: break-word;\n  flex: 1;\n}\n.chat-quick-mute {\n  opacity: 0;\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  font-size: .8rem;\n  padding: 0 .25rem;\n  transition: opacity .15s;\n}\n.chat-line:hover .chat-quick-mute {\n  opacity: 0.8;\n}\n.chat-quick-mute:hover {\n  opacity: 1 !important;\n  transform: scale(1.15);\n}\n.chat-dialog-footer {\n  display: flex;\n  align-items: center;\n  gap: .5rem;\n  padding: .85rem 1.25rem;\n  background: #0d1322;\n  border-top: 1px solid var(--color-rule);\n}\n\n/* Modals */\n.modal{\n  display:none;\n  position:fixed;\n  inset:0;\n  background:rgba(0,0,0,0.75);\n  backdrop-filter:blur(6px);\n  align-items:center;\n  justify-content:center;\n  z-index:100;\n  padding:1rem;\n}\n.modal-content{\n  background:var(--color-paper-2);\n  border:1px solid var(--color-rule);\n  border-radius:1.25rem;\n  padding:2rem;\n  max-width:480px;\n  width:100%;\n  box-shadow:0 25px 60px -15px rgba(0,0,0,0.8);\n}\n.modal-title{font-family:'Plus Jakarta Sans',sans-serif;font-size:1.3rem;font-weight:800;color:#fff;margin-bottom:1.25rem}\n.modal-actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:1.5rem}\n\n/* Toast */\n.toast{\n  position:fixed;\n  bottom:1.5rem;\n  right:1.5rem;\n  background:var(--color-paper-2);\n  border:1px solid var(--color-rule);\n  color:#fff;\n  padding:.85rem 1.35rem;\n  border-radius:.65rem;\n  font-weight:600;\n  font-size:.875rem;\n  box-shadow:0 15px 30px -5px rgba(0,0,0,0.6);\n  display:none;\n  z-index:200;\n}\n.empty-state{text-align:center;padding:3rem 1.5rem;color:var(--color-ink-2)}\n.empty-icon{font-size:2.5rem;margin-bottom:.75rem;opacity:.6}\n</style>\n</head>\n<body>\n<div class=\"container\">\n  <!-- Top Brand Header -->\n  <header>\n    <div class=\"brand\">\n      <div class=\"brand-title\">DotA & Friends</div>\n      <span class=\"brand-badge\">PvPGN Core PRO</span>\n      <div class=\"server-pill\"><span class=\"pulse-dot\"></span> dotaandfriends.ddns.net:6112 Online</div>\n    </div>\n    <div class=\"actions\">\n      <button class=\"btn btn-success\" onclick=\"openCreateModal()\">➕ Create Account</button>\n      <button class=\"btn btn-secondary\" onclick=\"refreshAll()\">🔄 Refresh</button>\n      <button class=\"btn btn-warning\" onclick=\"restartServer()\">⚡ Restart PvPGN</button>\n      <a href=\"/api/admin/db-backup\" class=\"btn btn-primary\" title=\"1-Click SQL Dump Download\">💾 Download DB Backup</a>\n      <a href=\"/admin/logout\" class=\"btn btn-danger\">🚪 Logout</a>\n    </div>\n  </header>\n\n  <!-- Metric Overview Cards -->\n  <div class=\"stats-grid\">\n    <div class=\"stat-card\">\n      <div class=\"stat-label\">Total Accounts</div>\n      <div class=\"stat-value\" id=\"statAccounts\">-- <span class=\"stat-sub\" id=\"statRoles\">--</span></div>\n    </div>\n    <div class=\"stat-card\">\n      <div class=\"stat-label\">Online Players</div>\n      <div class=\"stat-value\" id=\"statUsers\">-- <span class=\"stat-sub\" id=\"statInGame\">0 in games</span></div>\n    </div>\n    <div class=\"stat-card\">\n      <div class=\"stat-label\">Active Games / Lobbies</div>\n      <div class=\"stat-value\" id=\"statGames\">-- <span class=\"stat-sub\">Warcraft III</span></div>\n    </div>\n    <div class=\"stat-card\">\n      <div class=\"stat-label\">Server Channels</div>\n      <div class=\"stat-value\" id=\"statChannels\">12 <span class=\"stat-sub\">configured</span></div>\n    </div>\n    <div class=\"stat-card\">\n      <div class=\"stat-label\">Server Uptime</div>\n      <div class=\"stat-value\" id=\"statUptime\" style=\"font-size:1.15rem;margin-top:.45rem;font-family:'JetBrains Mono',monospace\">--</div>\n    </div>\n  </div>\n\n  <!-- Segmented Navigation Tabs -->\n  <div class=\"tabs-nav\">\n    <button class=\"tab-btn active\" onclick=\"switchTab('accountsTab')\">👥 Player Accounts <span class=\"tab-badge\" id=\"tabBadgeAccounts\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('gamesTab')\">🎮 Live Games <span class=\"tab-badge\" id=\"tabBadgeGames\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('playersTab')\">🟢 Online Sessions <span class=\"tab-badge\" id=\"tabBadgePlayers\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('chatTab')\">💬 Realm Chat &amp; Moderation <span class=\"tab-badge\" id=\"tabBadgeMutes\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('ladderTab')\">🏆 Ladder & Rankings <span class=\"tab-badge\" id=\"tabBadgeLadder\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('clansTab')\">🛡️ Clans & Teams <span class=\"tab-badge\" id=\"tabBadgeClans\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('bansTab')\">🚫 IP Bans & Security <span class=\"tab-badge\" id=\"tabBadgeBans\">0</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('announcementsTab')\">📢 MOTD & News</button>\n    <button class=\"tab-btn\" onclick=\"switchTab('channelsTab')\">💬 Channels <span class=\"tab-badge\" id=\"tabBadgeChannels\">12</span></button>\n    <button class=\"tab-btn\" onclick=\"switchTab('logsTab')\">📜 Server Logs</button>\n    <button class=\"tab-btn\" onclick=\"switchTab('systemTab')\">🗄️ Database & Resources</button>\n  </div>\n\n  <!-- TAB 1: ACCOUNTS -->\n  <div id=\"accountsTab\" class=\"tab-content active\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">\n          <span>Registered Player Accounts</span>\n          <div class=\"filter-tabs\">\n            <button class=\"filter-tab active\" data-filter=\"all\" onclick=\"setRoleFilter('all')\">All (<span id=\"countAll\">0</span>)</button>\n            <button class=\"filter-tab\" data-filter=\"staff\" onclick=\"setRoleFilter('staff')\">👑 Staff (<span id=\"countStaff\">0</span>)</button>\n            <button class=\"filter-tab\" data-filter=\"vip\" onclick=\"setRoleFilter('vip')\">💎 VIPs (<span id=\"countVips\">0</span>)</button>\n            <button class=\"filter-tab\" data-filter=\"bot\" onclick=\"setRoleFilter('bot')\">🤖 Bots (<span id=\"countBots\">0</span>)</button>\n            <button class=\"filter-tab\" data-filter=\"player\" onclick=\"setRoleFilter('player')\">👥 Players (<span id=\"countPlayers\">0</span>)</button>\n            <button class=\"filter-tab\" data-filter=\"locked\" onclick=\"setRoleFilter('locked')\">🔒 Locked (<span id=\"countLocked\">0</span>)</button>\n          </div>\n        </div>\n        <input type=\"text\" id=\"searchInput\" class=\"search-input\" placeholder=\"🔍 Search username, email, IP...\" oninput=\"filterAccounts()\">\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>UID</th>\n              <th>Username</th>\n              <th>Email</th>\n              <th>Role</th>\n              <th>Status</th>\n              <th>Last Login IP</th>\n              <th>Actions</th>\n            </tr>\n          </thead>\n          <tbody id=\"accountsTbody\">\n            <tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading player accounts...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 2: LIVE GAMES -->\n  <div id=\"gamesTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🎮 Live Games & Lobbies</div>\n        <div style=\"display:flex;gap:.5rem;align-items:center\">\n          <span style=\"font-size:.78rem;color:var(--color-ink-2)\">Auto-refreshes every 5s</span>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadOverview()\">🔄 Refresh Games</button>\n        </div>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Game ID</th>\n              <th>Game Name</th>\n              <th>Client Tag</th>\n              <th>Status</th>\n              <th>Slots / Players</th>\n              <th>Duration</th>\n              <th>Players in Lobby</th>\n            </tr>\n          </thead>\n          <tbody id=\"gamesTbody\">\n            <tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading active games...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 3: ONLINE PLAYERS -->\n  <div id=\"playersTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🟢 Connected Online Sessions</div>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadOverview()\">🔄 Refresh Sessions</button>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Player Username</th>\n              <th>Client</th>\n              <th>Current Location</th>\n              <th>Game ID</th>\n              <th>Connection Tag</th>\n            </tr>\n          </thead>\n          <tbody id=\"playersTbody\">\n            <tr><td colspan=\"5\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading online sessions...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB: REALM CHAT & MODERATION -->\n  <div id=\"chatTab\" class=\"tab-content\">\n    <!-- Active Mutes Mini Drawer -->\n    <div class=\"wc3-panel\" style=\"padding:1rem 1.25rem;margin-bottom:1rem\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.75rem\">\n        <div style=\"display:flex;align-items:center;gap:.75rem\">\n          <span style=\"font-weight:700;font-size:1rem;color:#fff;display:flex;align-items:center;gap:.4rem\">\n            🔇 Muted Players &amp; Penalties\n          </span>\n          <span class=\"badge badge-locked\" id=\"activeMutesCountBadge\">0 Active</span>\n        </div>\n        <div style=\"display:flex;gap:.5rem;align-items:center\">\n          <button class=\"btn btn-danger btn-sm\" onclick=\"openMuteModal()\">➕ Mute Player</button>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"toggleMutesList()\" id=\"toggleMutesBtn\">👁️ View Mute Details</button>\n          <button class=\"btn btn-warning btn-sm\" onclick=\"openPurgeModal()\">🗑️ Purge Logs</button>\n        </div>\n      </div>\n      <!-- Collapsible Detailed Mutes Table -->\n      <div id=\"mutesListWrap\" style=\"display:none;margin-top:1rem;border-top:1px solid var(--color-rule);padding-top:1rem\">\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>ID</th>\n                <th>Username</th>\n                <th>Reason</th>\n                <th>Muted By</th>\n                <th>Expires At</th>\n                <th>Status</th>\n                <th>Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"mutesTbody\">\n              <tr><td colspan=\"7\" style=\"text-align:center;padding:1.5rem;color:var(--color-ink-2)\">Loading active mutes...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <!-- Live Channel Chat Room Dialog -->\n    <div class=\"chat-dialog-container\">\n      <!-- Chat Dialog Header -->\n      <div class=\"chat-dialog-header\">\n        <div style=\"display:flex;align-items:center;gap:.75rem;flex-wrap:wrap\">\n          <span style=\"font-family:'Plus Jakarta Sans',sans-serif;font-weight:800;color:#fff;font-size:1.05rem;display:flex;align-items:center;gap:.5rem\">\n            💬 Live Realm Chat\n          </span>\n          <!-- Channel Dropdown -->\n          <div style=\"display:flex;align-items:center;gap:.35rem\">\n            <span style=\"font-size:.72rem;color:var(--color-ink-2);text-transform:uppercase;font-weight:600\">Channel:</span>\n            <select id=\"chatChannelFilter\" class=\"role-select\" onchange=\"onChannelFilterChange()\" style=\"font-weight:600;color:var(--color-frost);padding:.4rem .75rem\">\n              <option value=\"all\">🌟 All Channels (Global Stream)</option>\n              <option value=\"DotA and Friends\">DotA and Friends</option>\n              <option value=\"The Void\">The Void</option>\n              <option value=\"Warcraft III\">Warcraft III</option>\n              <option value=\"USA\">USA</option>\n            </select>\n          </div>\n          <!-- Source Filter -->\n          <div class=\"filter-tabs\" style=\"padding:.15rem .3rem\">\n            <button class=\"filter-tab active\" data-source-filter=\"all\" onclick=\"setSourceFilter('all')\">All Sources</button>\n            <button class=\"filter-tab\" data-source-filter=\"bnet\" onclick=\"setSourceFilter('bnet')\">⚔️ Battle.net</button>\n            <button class=\"filter-tab\" data-source-filter=\"web\" onclick=\"setSourceFilter('web')\">🌐 Web / Client</button>\n          </div>\n        </div>\n\n        <div style=\"display:flex;align-items:center;gap:.5rem;flex-wrap:wrap\">\n          <input type=\"text\" id=\"chatSearchInput\" class=\"search-input\" placeholder=\"🔍 Search text or user...\" oninput=\"debounceChatSearch()\" style=\"min-width:180px;padding:.4rem .75rem;font-size:.8rem\">\n          <button class=\"btn btn-secondary btn-sm\" id=\"autoScrollToggleBtn\" onclick=\"toggleAutoScroll()\">⬇️ Auto-scroll: ON</button>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadChatLogs()\">🔄 Refresh</button>\n        </div>\n      </div>\n\n      <!-- Chat Stream Body -->\n      <div class=\"chat-dialog-body\" id=\"chatStreamBox\">\n        <div style=\"color:var(--color-ink-2);text-align:center;padding:3rem\">Loading channel chats...</div>\n      </div>\n\n      <!-- Chat Dialog Footer / Admin Quick Send Bar -->\n      <form class=\"chat-dialog-footer\" id=\"adminSendForm\" onsubmit=\"sendAdminChatMessage(event)\">\n        <span style=\"font-weight:700;color:#FDE047;font-size:.8rem;white-space:nowrap;display:flex;align-items:center;gap:.3rem\">\n          👑 Admin Broadcast:\n        </span>\n        <input type=\"text\" id=\"adminMsgInput\" class=\"form-control\" placeholder=\"Type a message as Server Admin to send into channel...\" style=\"padding:.55rem .95rem;font-size:.85rem\" required autocomplete=\"off\">\n        <button type=\"submit\" class=\"btn btn-primary btn-sm\" style=\"white-space:nowrap;padding:.55rem 1.15rem\">🚀 Send</button>\n      </form>\n    </div>\n  </div>\n\n  <!-- TAB 4: LADDER & LEADERBOARD -->\n  <div id=\"ladderTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🏆 Warcraft III Ladder & Player Leaderboard</div>\n        <div style=\"display:flex;gap:.5rem;align-items:center\">\n          <input type=\"text\" id=\"ladderSearch\" class=\"search-input\" placeholder=\"🔍 Search player...\" oninput=\"filterLadder()\" style=\"min-width:200px\">\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadLadder()\">🔄 Refresh Ladder</button>\n        </div>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Rank</th>\n              <th>Username</th>\n              <th>Level & XP</th>\n              <th>Solo Score (W / L)</th>\n              <th>Team Score (W / L)</th>\n              <th>Total Games</th>\n              <th>Win Rate</th>\n            </tr>\n          </thead>\n          <tbody id=\"ladderTbody\">\n            <tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading ladder rankings...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 5: CLANS & TEAMS -->\n  <div id=\"clansTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🛡️ Registered Battle.net Clans & Teams</div>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadClans()\">🔄 Refresh Clans</button>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Clan ID</th>\n              <th>Tag</th>\n              <th>Clan Name</th>\n              <th>Chieftain</th>\n              <th>Members</th>\n              <th>Creation Date</th>\n              <th>Actions</th>\n            </tr>\n          </thead>\n          <tbody id=\"clansTbody\">\n            <tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading clans...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 6: IP BANS & SECURITY -->\n  <div id=\"bansTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🚫 IP Bans & Connection Blacklist</div>\n        <div style=\"display:flex;gap:.5rem;align-items:center\">\n          <button class=\"btn btn-danger btn-sm\" onclick=\"openBanModal()\">➕ Add IP Ban</button>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadBans()\">🔄 Refresh Bans</button>\n        </div>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Target Account</th>\n              <th>IP / Subnet CIDR</th>\n              <th>Banned By</th>\n              <th>Reason / Note</th>\n              <th>Date</th>\n              <th>Expires</th>\n              <th>Actions</th>\n            </tr>\n          </thead>\n          <tbody id=\"bansTbody\">\n            <tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading banlist...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 7: ANNOUNCEMENTS & MOTD -->\n  <div id=\"announcementsTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">📢 Server Announcements, MOTD & News</div>\n        <div style=\"display:flex;gap:.5rem\">\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadAnnouncements()\">🔄 Reload from Disk</button>\n          <button class=\"btn btn-success btn-sm\" onclick=\"saveAnnouncements()\">💾 Save & Apply</button>\n        </div>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(380px, 1fr));gap:1.25rem\">\n        <div>\n          <div class=\"form-group\">\n            <label>⚔️ Warcraft III Login MOTD (w3motd.txt)</label>\n            <div style=\"font-size:.75rem;color:var(--color-ink-2);margin-bottom:.4rem\">Popup dialog displayed to players when entering Battle.net</div>\n            <textarea id=\"editW3Motd\" class=\"form-control\" rows=\"8\" placeholder=\"Welcome message...\"></textarea>\n          </div>\n          <div class=\"form-group\">\n            <label>🌐 Battle.net Global MOTD (bnmotd.txt)</label>\n            <textarea id=\"editBnMotd\" class=\"form-control\" rows=\"5\" placeholder=\"Battle.net MOTD...\"></textarea>\n          </div>\n        </div>\n        <div>\n          <div class=\"form-group\">\n            <label>📰 Battle.net Server News (news.txt)</label>\n            <div style=\"font-size:.75rem;color:var(--color-ink-2);margin-bottom:.4rem\">Text displayed in the News tab in game</div>\n            <textarea id=\"editNews\" class=\"form-control\" rows=\"8\" placeholder=\"News updates...\"></textarea>\n          </div>\n          <div class=\"form-group\">\n            <label>💬 Channel Welcome Topics (topics.conf)</label>\n            <div style=\"font-size:.75rem;color:var(--color-ink-2);margin-bottom:.4rem\">Format: ChannelName &lt;tab&gt; TopicText</div>\n            <textarea id=\"editTopics\" class=\"form-control\" rows=\"5\" placeholder=\"Channel topics...\"></textarea>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 8: CHANNELS -->\n  <div id=\"channelsTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">💬 Server Channels & Active Chat Rooms</div>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadOverview()\">🔄 Refresh Channels</button>\n      </div>\n      <div class=\"channel-grid\" id=\"channelsGrid\">\n        <div style=\"grid-column:1/-1;text-align:center;padding:2.5rem;color:var(--color-ink-2)\">Loading channels...</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 9: SERVER LOGS -->\n  <div id=\"logsTab\" class=\"tab-content\">\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">\n          <span>📜 bnetd.log Live Diagnostics</span>\n          <div class=\"filter-tabs\">\n            <button class=\"filter-tab active\" data-log-filter=\"all\" onclick=\"setLogFilter('all')\">All</button>\n            <button class=\"filter-tab\" data-log-filter=\"info\" onclick=\"setLogFilter('info')\">[info]</button>\n            <button class=\"filter-tab\" data-log-filter=\"warn\" onclick=\"setLogFilter('warn')\">[warn]</button>\n            <button class=\"filter-tab\" data-log-filter=\"error\" onclick=\"setLogFilter('error')\">[error]</button>\n          </div>\n        </div>\n        <div style=\"display:flex;gap:.5rem;align-items:center;flex-wrap:wrap\">\n          <input type=\"text\" id=\"logSearch\" class=\"search-input\" placeholder=\"🔍 Search in logs...\" oninput=\"filterLogs()\" style=\"min-width:200px\">\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadLogs()\">🔄 Refresh</button>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"copyLogs()\">📋 Copy Logs</button>\n        </div>\n      </div>\n      <div class=\"log-terminal\" id=\"logViewer\">\n        <div style=\"color:var(--color-ink-2)\">Loading bnetd server log tail...</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 10: DATABASE & SYSTEM -->\n  <div id=\"systemTab\" class=\"tab-content\">\n    <div class=\"db-banner\">\n      <div>\n        <div style=\"font-weight:700;color:#fff;font-size:1.05rem;margin-bottom:.3rem\">PvPGN Core Database & Diagnostics</div>\n        <div style=\"font-size:.85rem;color:var(--color-ink-2)\">\n          Host: <code class=\"copy-chip\" onclick=\"copyText('mysql', 'Host copied!')\">mysql</code> &middot;\n          DB: <code class=\"copy-chip\" onclick=\"copyText('pvpgn', 'Database copied!')\">pvpgn</code> &middot;\n          User: <code class=\"copy-chip\" onclick=\"copyText('pvpgn', 'User copied!')\">pvpgn</code> &middot;\n          Password: <code class=\"copy-chip\" onclick=\"copyText('siddnoob', 'Password copied!')\">siddnoob 📋</code> &middot;\n          Port: <code class=\"copy-chip\" onclick=\"copyText('3306')\">3306</code>\n        </div>\n      </div>\n      <div style=\"display:flex;gap:.6rem;flex-wrap:wrap\">\n        <a href=\"/api/admin/db-backup\" class=\"btn btn-success\">💾 1-Click SQL Backup</a>\n        <a href=\"/db/?server=mysql&username=pvpgn&db=pvpgn\" target=\"_blank\" class=\"btn btn-primary\">🚀 Launch Adminer GUI</a>\n      </div>\n    </div>\n\n    <!-- Live Docker Container Resource Graphs -->\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">📊 Live Docker Container Resources (CPU & RAM)</div>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadContainers()\">🔄 Refresh Metrics</button>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Service</th>\n              <th>Status</th>\n              <th>CPU Usage</th>\n              <th>Memory Usage</th>\n              <th>Ports Mapping</th>\n            </tr>\n          </thead>\n          <tbody id=\"containersTbody\">\n            <tr><td colspan=\"5\" style=\"text-align:center;padding:2rem;color:var(--color-ink-2)\">Loading container metrics...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <!-- MySQL Tables -->\n    <div class=\"wc3-panel\">\n      <div class=\"panel-header\">\n        <div class=\"panel-title\">🗄️ MySQL Database Tables & Storage</div>\n        <div style=\"display:flex;gap:.5rem\">\n          <a href=\"/api/admin/db-backup\" class=\"btn btn-secondary btn-sm\">💾 Download SQL Dump</a>\n          <button class=\"btn btn-secondary btn-sm\" onclick=\"loadDbStats()\">🔄 Refresh DB</button>\n        </div>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>Table Name</th>\n              <th>Estimated Rows</th>\n              <th>Storage Size (KB)</th>\n              <th>Type / Description</th>\n            </tr>\n          </thead>\n          <tbody id=\"dbTablesTbody\">\n            <tr><td colspan=\"4\" style=\"text-align:center;padding:2rem;color:var(--color-ink-2)\">Loading database stats...</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- Modal 1: Create Account -->\n<div id=\"createModal\" class=\"modal\">\n  <div class=\"modal-content\">\n    <div class=\"modal-title\">Create Player Account</div>\n    <form id=\"createForm\">\n      <div class=\"form-group\">\n        <label>Username</label>\n        <input type=\"text\" id=\"newUsername\" class=\"form-control\" placeholder=\"PlayerName (3-15 chars)\" required minlength=\"3\" maxlength=\"15\">\n      </div>\n      <div class=\"form-group\">\n        <label>Password</label>\n        <input type=\"password\" id=\"newPassword\" class=\"form-control\" placeholder=\"6-12 characters\" required minlength=\"6\" maxlength=\"12\">\n      </div>\n      <div class=\"form-group\">\n        <label>Email Address</label>\n        <input type=\"email\" id=\"newEmail\" class=\"form-control\" placeholder=\"player@example.com\" required>\n      </div>\n      <div class=\"form-group\">\n        <label>Role</label>\n        <select id=\"newRole\" class=\"form-control\">\n          <option value=\"player\">Player (Group 1 - Default)</option>\n          <option value=\"vip\">✨ VIP (Group 32)</option>\n          <option value=\"vvip\">⭐ VVIP (Group 48)</option>\n          <option value=\"svip\">🌟 SVIP (Group 64)</option>\n          <option value=\"mvp\">💎 MVP (Group 96)</option>\n          <option value=\"moderator\">🛡️ Moderator (Group 128)</option>\n          <option value=\"admin\">⚡ Admin (Group 254)</option>\n          <option value=\"owner\">👑 Owner (Group 255)</option>\n          <option value=\"bot\">🤖 Bot (GHost / Auto-Host)</option>\n        </select>\n      </div>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closeCreateModal()\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-success\">Create Account</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal 2: Reset Password -->\n<div id=\"passModal\" class=\"modal\">\n  <div class=\"modal-content\">\n    <div class=\"modal-title\">Reset Password for <span id=\"passUsername\" style=\"color:var(--color-frost)\"></span></div>\n    <form id=\"passForm\">\n      <input type=\"hidden\" id=\"passUid\">\n      <div class=\"form-group\">\n        <label>New Password</label>\n        <input type=\"password\" id=\"passInput\" class=\"form-control\" placeholder=\"6-12 characters\" required minlength=\"6\" maxlength=\"12\">\n      </div>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closePassModal()\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-primary\">Save Password</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal 3: Add IP Ban -->\n<div id=\"banModal\" class=\"modal\">\n  <div class=\"modal-content\">\n    <div class=\"modal-title\">Ban Account or IP Address</div>\n    <form id=\"banForm\">\n      <div class=\"form-group\">\n        <label>Account Username (Optional if IP provided)</label>\n        <input type=\"text\" id=\"banUserInput\" class=\"form-control\" placeholder=\"e.g. test or player1\">\n      </div>\n      <div class=\"form-group\">\n        <label>IP Address or Subnet CIDR</label>\n        <input type=\"text\" id=\"banIpInput\" class=\"form-control\" placeholder=\"e.g. 192.168.1.100 or 10.0.0.0/24\" required>\n      </div>\n      <div class=\"form-group\">\n        <label>Ban Duration</label>\n        <select id=\"banDurationInput\" class=\"form-control\">\n          <option value=\"0\">Permanent</option>\n          <option value=\"3600\">1 Hour</option>\n          <option value=\"43200\">12 Hours</option>\n          <option value=\"86400\">1 Day (24 Hours)</option>\n          <option value=\"259200\">3 Days</option>\n          <option value=\"604800\">7 Days (1 Week)</option>\n          <option value=\"2592000\">30 Days (1 Month)</option>\n        </select>\n      </div>\n      <div class=\"form-group\">\n        <label>Reason / Note</label>\n        <input type=\"text\" id=\"banReasonInput\" class=\"form-control\" placeholder=\"e.g. Bot spam, griefing, multi-hack\" required>\n      </div>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closeBanModal()\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-danger\">🚫 Enforce Ban</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal 4: Clan Roster -->\n<div id=\"rosterModal\" class=\"modal\">\n  <div class=\"modal-content\" style=\"max-width:700px\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem\">\n      <div class=\"modal-title\" style=\"margin-bottom:0\">\n        Clan Roster: <span id=\"rosterClanName\" style=\"color:var(--color-frost)\"></span>\n        <span class=\"badge badge-admin\" id=\"rosterClanTag\" style=\"margin-left:.5rem\"></span>\n      </div>\n      <button class=\"btn btn-secondary btn-sm\" onclick=\"closeRosterModal()\">✕</button>\n    </div>\n    <div class=\"table-wrap\" style=\"max-height:380px;overflow-y:auto\">\n      <table>\n        <thead>\n          <tr>\n            <th>UID</th>\n            <th>Member</th>\n            <th>Rank</th>\n            <th>Joined</th>\n            <th>Last Login</th>\n            <th>Actions</th>\n          </tr>\n        </thead>\n        <tbody id=\"rosterTbody\">\n          <tr><td colspan=\"6\" style=\"text-align:center;padding:2rem;color:var(--color-ink-2)\">Loading clan members...</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"modal-actions\" style=\"margin-top:1.25rem\">\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closeRosterModal()\">Close</button>\n    </div>\n  </div>\n</div>\n\n<!-- Modal 5: Mute Player -->\n<div id=\"muteModal\" class=\"modal\">\n  <div class=\"modal-content\">\n    <div class=\"modal-title\">🔇 Mute Player from Realm Chat</div>\n    <form id=\"muteForm\">\n      <div class=\"form-group\">\n        <label>Username</label>\n        <input type=\"text\" id=\"muteUsernameInput\" class=\"form-control\" placeholder=\"PlayerName\" required>\n      </div>\n      <div class=\"form-group\">\n        <label>Mute Duration</label>\n        <select id=\"muteDurationSelect\" class=\"form-control\">\n          <option value=\"15\">15 Minutes</option>\n          <option value=\"60\">1 Hour</option>\n          <option value=\"360\">6 Hours</option>\n          <option value=\"1440\" selected>24 Hours (1 Day)</option>\n          <option value=\"10080\">7 Days</option>\n          <option value=\"43200\">30 Days</option>\n          <option value=\"0\">Permanent Mute</option>\n        </select>\n      </div>\n      <div class=\"form-group\">\n        <label>Reason / Note</label>\n        <input type=\"text\" id=\"muteReasonInput\" class=\"form-control\" placeholder=\"e.g. Offensive language, spamming\" required>\n      </div>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closeMuteModal()\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-danger\">🔇 Enforce Mute</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal 6: Purge Chat Logs -->\n<div id=\"purgeModal\" class=\"modal\">\n  <div class=\"modal-content\">\n    <div class=\"modal-title\">🗑️ Purge Realm Chat Logs</div>\n    <form id=\"purgeForm\">\n      <div class=\"form-group\">\n        <label>Select Purge Retention</label>\n        <select id=\"purgeRangeSelect\" class=\"form-control\">\n          <option value=\"7d\">Delete logs older than 7 days</option>\n          <option value=\"30d\">Delete logs older than 30 days</option>\n          <option value=\"all\">Purge ALL chat logs (Truncate table)</option>\n        </select>\n      </div>\n      <p style=\"font-size:.8rem;color:var(--color-danger);margin-bottom:1rem\">⚠️ This action permanently deletes chat audit logs from MySQL.</p>\n      <div class=\"modal-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closePurgeModal()\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-danger\">Confirm Purge</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<div id=\"toast\" class=\"toast\"></div>\n\n<script>\nlet allAccounts = [];\nlet allLadder = [];\nlet allBans = [];\nlet allLogs = [];\nlet currentRoleFilter = 'all';\nlet currentLogFilter = 'all';\n\nfunction showToast(msg, isErr) {\n  const t = document.getElementById('toast');\n  t.textContent = msg;\n  t.style.borderLeft = isErr ? '4px solid #ef4444' : '4px solid #10b981';\n  t.style.display = 'block';\n  setTimeout(() => { t.style.display = 'none'; }, 3500);\n}\n\nfunction copyText(text, successMsg) {\n  navigator.clipboard.writeText(text).then(() => {\n    showToast(successMsg || 'Copied to clipboard!');\n  }).catch(() => {\n    showToast('Failed to copy', true);\n  });\n}\n\nfunction switchTab(tabId) {\n  document.querySelectorAll('.tab-btn').forEach(btn => {\n    btn.classList.toggle('active', btn.getAttribute('onclick').includes(tabId));\n  });\n  document.querySelectorAll('.tab-content').forEach(p => {\n    p.classList.toggle('active', p.id === tabId);\n  });\n\n  if (tabId === 'logsTab') loadLogs();\n  if (tabId === 'systemTab') { loadContainers(); loadDbStats(); }\n  if (tabId === 'gamesTab' || tabId === 'playersTab' || tabId === 'channelsTab') loadOverview();\n  if (tabId === 'ladderTab') loadLadder();\n  if (tabId === 'clansTab') loadClans();\n  if (tabId === 'bansTab') loadBans();\n  if (tabId === 'announcementsTab') loadAnnouncements();\n  if (tabId === 'chatTab') { loadChatMutes(); loadChatChannels(); loadChatLogs(); }\n}\n\nfunction setRoleFilter(filter) {\n  currentRoleFilter = filter;\n  document.querySelectorAll('.filter-tab[data-filter]').forEach(b => {\n    b.classList.toggle('active', b.getAttribute('data-filter') === filter);\n  });\n  filterAccounts();\n}\n\nfunction setLogFilter(filter) {\n  currentLogFilter = filter;\n  document.querySelectorAll('.filter-tab[data-log-filter]').forEach(b => {\n    b.classList.toggle('active', b.getAttribute('data-log-filter') === filter);\n  });\n  filterLogs();\n}\n\n// -----------------------------\n// TAB 1: Accounts\n// -----------------------------\nfunction getAccountRole(a) {\n  if (a.auth_botlogin === 'true') return 'bot';\n  const g = parseInt(a.auth_command_groups || '1', 10);\n  const isAdmin = a.auth_admin === 'true';\n  const isOp = a.auth_operator === 'true';\n  if (isAdmin && g >= 255) return 'owner';\n  if (isAdmin || g >= 200) return 'admin';\n  if (isOp || g >= 128) return 'moderator';\n  if (g >= 96) return 'mvp';\n  if (g >= 64) return 'svip';\n  if (g >= 48) return 'vvip';\n  if (g >= 32) return 'vip';\n  return 'player';\n}\n\nfunction getRoleBadge(role) {\n  switch (role) {\n    case 'owner':\n      return '<span class=\"badge\" style=\"background:rgba(239,68,68,0.18);color:#FCA5A5;border:1px solid rgba(239,68,68,0.4)\">👑 Owner (255)</span>';\n    case 'admin':\n      return '<span class=\"badge badge-admin\">⚡ Admin (254)</span>';\n    case 'moderator':\n      return '<span class=\"badge badge-op\">🛡️ Mod (128)</span>';\n    case 'mvp':\n      return '<span class=\"badge\" style=\"background:rgba(192,132,252,0.18);color:#E9D5FF;border:1px solid rgba(192,132,252,0.4)\">💎 MVP (96)</span>';\n    case 'svip':\n      return '<span class=\"badge\" style=\"background:rgba(244,63,94,0.18);color:#FDA4AF;border:1px solid rgba(244,63,94,0.4)\">🌟 SVIP (64)</span>';\n    case 'vvip':\n      return '<span class=\"badge\" style=\"background:rgba(234,179,8,0.18);color:#FEF08A;border:1px solid rgba(234,179,8,0.4)\">⭐ VVIP (48)</span>';\n    case 'vip':\n      return '<span class=\"badge\" style=\"background:rgba(16,185,129,0.18);color:#A7F3D0;border:1px solid rgba(16,185,129,0.4)\">✨ VIP (32)</span>';\n    case 'bot':\n      return '<span class=\"badge badge-bot\">🤖 Bot</span>';\n    default:\n      return '<span class=\"badge badge-user\">Player</span>';\n  }\n}\n\nasync function loadAccounts() {\n  try {\n    const res = await fetch('/api/admin/accounts');\n    const data = await res.json();\n    if (data.success) {\n      allAccounts = (data.accounts || []).filter(a => a.uid > 0 && (a.username || a.acct_username));\n      document.getElementById('statAccounts').innerHTML = allAccounts.length + ' <span class=\"stat-sub\" id=\"statRoles\">--</span>';\n      document.getElementById('tabBadgeAccounts').textContent = allAccounts.length;\n\n      const staff = allAccounts.filter(a => {\n        const r = getAccountRole(a);\n        return r === 'owner' || r === 'admin' || r === 'moderator';\n      }).length;\n      const vips = allAccounts.filter(a => {\n        const r = getAccountRole(a);\n        return r === 'mvp' || r === 'svip' || r === 'vvip' || r === 'vip';\n      }).length;\n      const bots = allAccounts.filter(a => a.auth_botlogin === 'true').length;\n      const players = allAccounts.filter(a => getAccountRole(a) === 'player').length;\n      const locked = allAccounts.filter(a => a.auth_lock === 'true').length;\n\n      document.getElementById('statRoles').textContent = '(' + staff + ' Staff, ' + vips + ' VIPs, ' + bots + ' Bots)';\n      document.getElementById('countAll').textContent = allAccounts.length;\n      if (document.getElementById('countStaff')) document.getElementById('countStaff').textContent = staff;\n      if (document.getElementById('countVips')) document.getElementById('countVips').textContent = vips;\n      if (document.getElementById('countBots')) document.getElementById('countBots').textContent = bots;\n      if (document.getElementById('countPlayers')) document.getElementById('countPlayers').textContent = players;\n      if (document.getElementById('countLocked')) document.getElementById('countLocked').textContent = locked;\n\n      filterAccounts();\n    }\n  } catch(e) {\n    showToast('Failed to load accounts: ' + e.message, true);\n  }\n}\n\nfunction renderAccounts(accounts) {\n  const tbody = document.getElementById('accountsTbody');\n  if (accounts.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"7\" style=\"text-align:center;padding:2.5rem;color:var(--color-ink-2)\">No player accounts found matching criteria</td></tr>';\n    return;\n  }\n  tbody.innerHTML = accounts.map(a => {\n    const roleVal = getAccountRole(a);\n    const isLocked = a.auth_lock === 'true';\n    const uname = escapeHtml(a.username || a.acct_username);\n    const roleBadge = getRoleBadge(roleVal);\n    const statusBadge = isLocked ? '<span class=\"badge badge-locked\">🔒 Locked</span>' :\n                                   '<span class=\"badge badge-active\">Active</span>';\n    return '<tr>' +\n      '<td style=\"font-weight:700;color:var(--color-ink-2);font-family:monospace\">#' + a.uid + '</td>' +\n      '<td style=\"font-weight:700;color:#fff\">' + uname + '</td>' +\n      '<td style=\"color:var(--color-ink-2)\">' + escapeHtml(a.acct_email || '--') + '</td>' +\n      '<td>' + roleBadge + '</td>' +\n      '<td>' + statusBadge + '</td>' +\n      '<td style=\"font-family:monospace;color:var(--color-ink-2);font-size:.8rem\">' + escapeHtml(a.acct_lastlogin_ip || 'Never logged in') + '</td>' +\n      '<td>' +\n        '<div class=\"action-btns\">' +\n          '<button class=\"action-btn btn-secondary\" onclick=\"openPassModal(' + a.uid + ', this.dataset.uname)\" data-uname=\"' + uname + '\">🔑 Pass</button>' +\n          '<select class=\"role-select\" onchange=\"toggleRole(' + a.uid + ', this.value)\">' +\n            '<option value=\"owner\"' + (roleVal === 'owner' ? ' selected' : '') + '>👑 Owner (255)</option>' +\n            '<option value=\"admin\"' + (roleVal === 'admin' ? ' selected' : '') + '>⚡ Admin (254)</option>' +\n            '<option value=\"moderator\"' + (roleVal === 'moderator' ? ' selected' : '') + '>🛡️ Mod (128)</option>' +\n            '<option value=\"mvp\"' + (roleVal === 'mvp' ? ' selected' : '') + '>💎 MVP (96)</option>' +\n            '<option value=\"svip\"' + (roleVal === 'svip' ? ' selected' : '') + '>🌟 SVIP (64)</option>' +\n            '<option value=\"vvip\"' + (roleVal === 'vvip' ? ' selected' : '') + '>⭐ VVIP (48)</option>' +\n            '<option value=\"vip\"' + (roleVal === 'vip' ? ' selected' : '') + '>✨ VIP (32)</option>' +\n            '<option value=\"bot\"' + (roleVal === 'bot' ? ' selected' : '') + '>🤖 Bot (GHost)</option>' +\n            '<option value=\"player\"' + (roleVal === 'player' ? ' selected' : '') + '>Player (1)</option>' +\n          '</select>' +\n          '<button class=\"action-btn ' + (isLocked ? 'btn-success' : 'btn-warning') + '\" onclick=\"toggleLock(' + a.uid + ', ' + (!isLocked) + ')\">' + (isLocked ? '🔓' : '🔒') + '</button>' +\n          '<button class=\"action-btn btn-danger\" onclick=\"deleteAccount(' + a.uid + ', this.dataset.uname)\" data-uname=\"' + uname + '\">🗑️</button>' +\n        '</div>' +\n      '</td>' +\n    '</tr>';\n  }).join('');\n}\n\nfunction filterAccounts() {\n  const q = document.getElementById('searchInput').value.toLowerCase().trim();\n  let list = allAccounts;\n\n  if (currentRoleFilter === 'staff') {\n    list = list.filter(a => {\n      const r = getAccountRole(a);\n      return r === 'owner' || r === 'admin' || r === 'moderator';\n    });\n  } else if (currentRoleFilter === 'vip') {\n    list = list.filter(a => {\n      const r = getAccountRole(a);\n      return r === 'mvp' || r === 'svip' || r === 'vvip' || r === 'vip';\n    });\n  } else if (currentRoleFilter === 'bot') {\n    list = list.filter(a => a.auth_botlogin === 'true');\n  } else if (currentRoleFilter === 'player') {\n    list = list.filter(a => getAccountRole(a) === 'player');\n  } else if (currentRoleFilter === 'locked') {\n    list = list.filter(a => a.auth_lock === 'true');\n  }\n\n  if (q) {\n    list = list.filter(a =>\n      (a.username && a.username.toLowerCase().includes(q)) ||\n      (a.acct_email && a.acct_email.toLowerCase().includes(q)) ||\n      (a.acct_lastlogin_ip && a.acct_lastlogin_ip.includes(q))\n    );\n  }\n  renderAccounts(list);\n}\n\n// -----------------------------\n// TAB 2, 3, 8: Overview (Games, Sessions, Channels)\n// -----------------------------\nasync function loadOverview() {\n  try {\n    const res = await fetch('/api/admin/overview');\n    const d = await res.json();\n    if (d.success) {\n      document.getElementById('statUsers').innerHTML = (d.status.users || 0) + ' <span class=\"stat-sub\">' + (d.war3Users || 0) + ' War3</span>';\n      document.getElementById('statGames').innerHTML = (d.status.games || 0) + ' <span class=\"stat-sub\">' + (d.war3Games || 0) + ' War3</span>';\n      document.getElementById('statUptime').textContent = d.status.uptime || 'Running';\n      document.getElementById('tabBadgeGames').textContent = d.games ? d.games.length : 0;\n      document.getElementById('tabBadgePlayers').textContent = d.activeUsers ? d.activeUsers.length : 0;\n      document.getElementById('tabBadgeChannels').textContent = d.channels ? d.channels.length : 12;\n\n      renderGames(d.games || []);\n      renderPlayers(d.activeUsers || []);\n      renderChannels(d.channels || []);\n    }\n  } catch(e) {\n    console.error('Failed to load overview:', e);\n  }\n}\n\nfunction renderGames(games) {\n  const tbody = document.getElementById('gamesTbody');\n  if (games.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"7\">' +\n      '<div class=\"empty-state\">' +\n        '<div class=\"empty-icon\">🎮</div>' +\n        '<div style=\"font-weight:700;color:#fff;font-size:1rem;margin-bottom:.35rem\">No Active Games or Lobbies</div>' +\n        '<div>Host a Warcraft III Frozen Throne game on Battle.net to monitor live slots and players here.</div>' +\n      '</div>' +\n    '</td></tr>';\n    return;\n  }\n  tbody.innerHTML = games.map(g => {\n    const isStarted = g.status === 'started';\n    const statusBadge = isStarted ? '<span class=\"badge badge-started\">▶ Started</span>' : '<span class=\"badge badge-open\">🟢 Lobby Open</span>';\n    const playersList = (g.players && g.players.length > 0) ? g.players.map(p => escapeHtml(p)).join(', ') : 'Waiting for players';\n    return '<tr>' +\n      '<td style=\"font-family:monospace;font-weight:700\">#' + g.id + '</td>' +\n      '<td style=\"font-weight:700;color:#fff\">' + escapeHtml(g.name) + '</td>' +\n      '<td><span class=\"badge badge-user\">' + escapeHtml(g.tag || 'W3XP') + '</span></td>' +\n      '<td>' + statusBadge + '</td>' +\n      '<td style=\"font-family:monospace\">' + g.count + ' / ' + (g.slots || '--') + '</td>' +\n      '<td style=\"font-family:monospace;color:var(--color-frost)\">' + (g.starttime ? Math.floor((Date.now()/1000 - g.starttime)/60) + 'm' : 'Just created') + '</td>' +\n      '<td style=\"color:var(--color-ink-2);font-size:.8rem\">' + playersList + '</td>' +\n    '</tr>';\n  }).join('');\n}\n\nfunction renderPlayers(players) {\n  const tbody = document.getElementById('playersTbody');\n  if (players.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"5\">' +\n      '<div class=\"empty-state\">' +\n        '<div class=\"empty-icon\">🟢</div>' +\n        '<div style=\"font-weight:700;color:#fff;font-size:1rem;margin-bottom:.35rem\">No Players Currently Online</div>' +\n        '<div>Server listening on port 6112. Connect via Warcraft III gateway to see live sessions.</div>' +\n      '</div>' +\n    '</td></tr>';\n    return;\n  }\n  tbody.innerHTML = players.map(p => {\n    let statusBadge = '<span class=\"badge badge-user\">In Channel</span>';\n    if (p.presence === 'dnd') {\n      statusBadge = '<span class=\"badge badge-locked\" title=\"' + escapeHtml(p.statusText || 'Do Not Disturb') + '\">⛔ DND</span>';\n    } else if (p.presence === 'away') {\n      statusBadge = '<span class=\"badge badge-gold\" title=\"' + escapeHtml(p.statusText || 'Away') + '\">🌙 Away</span>';\n    } else if (p.gameId && p.gameId !== '0') {\n      statusBadge = '<span class=\"badge badge-active\">🎮 Game #' + escapeHtml(p.gameId) + '</span>';\n    }\n    return '<tr>' +\n      '<td style=\"font-weight:700;color:#fff\">' + escapeHtml(p.username) + '</td>' +\n      '<td><span class=\"badge badge-user\">' + escapeHtml(p.client || p.tag) + '</span></td>' +\n      '<td style=\"color:var(--color-frost)\">' + escapeHtml(p.channel || p.location || (p.gameId && p.gameId !== \"0\" ? ('Game #' + p.gameId) : 'DotA and Friends')) + '</td>' +\n      '<td>' + statusBadge + '</td>' +\n      '<td style=\"font-family:monospace;color:var(--color-ink-2)\">' + escapeHtml(p.tag) + '</td>' +\n    '</tr>';\n  }).join('');\n}\n\nfunction renderChannels(channels) {\n  const grid = document.getElementById('channelsGrid');\n  if (channels.length === 0) {\n    channels = [\"DotA and Friends\", \"The Void\", \"Warcraft 3 Frozen Throne\", \"Human Castle\", \"Orc Stronghold\", \"Undead Necropolis\", \"Night Elf Tree of Life\", \"Dragon Roost\", \"Chat\", \"Backstage\", \"Moderated Support\"];\n  }\n  grid.innerHTML = channels.map(c => '<div class=\"channel-card\">' +\n    '<div class=\"channel-name\">📢 ' + escapeHtml(c) + '</div>' +\n    '<div class=\"channel-meta\">' +\n      '<span>PvPGN Standard Channel</span>' +\n      '<span class=\"badge badge-active\">Available</span>' +\n    '</div>' +\n  '</div>').join('');\n}\n\n// -----------------------------\n// TAB 4: Ladder & Rankings\n// -----------------------------\nasync function loadLadder() {\n  try {\n    const res = await fetch('/api/admin/ladder');\n    const d = await res.json();\n    if (d.success) {\n      allLadder = d.ladder || [];\n      document.getElementById('tabBadgeLadder').textContent = allLadder.length;\n      renderLadder(allLadder);\n    }\n  } catch(e) {\n    console.error('Failed to load ladder:', e);\n  }\n}\n\nfunction renderLadder(ladder) {\n  const tbody = document.getElementById('ladderTbody');\n  if (ladder.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"7\">' +\n      '<div class=\"empty-state\">' +\n        '<div class=\"empty-icon\">🏆</div>' +\n        '<div style=\"font-weight:700;color:#fff;font-size:1rem;margin-bottom:.35rem\">No Ladder Records Found</div>' +\n        '<div>Play games on the server to record match statistics and populate rankings.</div>' +\n      '</div>' +\n    '</td></tr>';\n    return;\n  }\n  tbody.innerHTML = ladder.map(r => {\n    let rankBadge = '<span style=\"font-weight:700;color:var(--color-ink-2)\">#' + r.rank + '</span>';\n    if (r.rank === 1) rankBadge = '<span class=\"badge badge-gold\">🥇 #1 Champion</span>';\n    else if (r.rank === 2) rankBadge = '<span class=\"badge badge-silver\">🥈 #2 Runner-up</span>';\n    else if (r.rank === 3) rankBadge = '<span class=\"badge badge-bronze\">🥉 #3 Third</span>';\n\n    return '<tr>' +\n      '<td>' + rankBadge + '</td>' +\n      '<td style=\"font-weight:700;color:#fff\">' + escapeHtml(r.username) + '</td>' +\n      '<td><span class=\"badge badge-user\">Lv ' + r.solo_level + '</span> <span style=\"font-size:.78rem;color:var(--color-frost);margin-left:.3rem\">' + r.solo_xp + ' XP</span></td>' +\n      '<td style=\"font-family:monospace\"><span style=\"color:#6EE7B7\">' + r.solo_wins + 'W</span> / <span style=\"color:#FCA5A5\">' + r.solo_losses + 'L</span></td>' +\n      '<td style=\"font-family:monospace\"><span style=\"color:#6EE7B7\">' + r.team_wins + 'W</span> / <span style=\"color:#FCA5A5\">' + r.team_losses + 'L</span></td>' +\n      '<td style=\"font-family:monospace;font-weight:700\">' + r.totalGames + '</td>' +\n      '<td><span class=\"badge ' + (parseFloat(r.winRate) >= 50 ? 'badge-active' : 'badge-user') + '\">' + r.winRate + '</span></td>' +\n    '</tr>';\n  }).join('');\n}\n\nfunction filterLadder() {\n  const q = document.getElementById('ladderSearch').value.toLowerCase().trim();\n  const filtered = q ? allLadder.filter(r => r.username.toLowerCase().includes(q)) : allLadder;\n  renderLadder(filtered);\n}\n\n// -----------------------------\n// TAB 5: Clans & Teams\n// -----------------------------\nasync function loadClans() {\n  try {\n    const res = await fetch('/api/admin/clans');\n    const d = await res.json();\n    const tbody = document.getElementById('clansTbody');\n    if (d.success) {\n      const clans = d.clans || [];\n      document.getElementById('tabBadgeClans').textContent = clans.length;\n      if (clans.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"7\">' +\n          '<div class=\"empty-state\">' +\n            '<div class=\"empty-icon\">🛡️</div>' +\n            '<div style=\"font-weight:700;color:#fff;font-size:1rem;margin-bottom:.35rem\">No Clans Established Yet</div>' +\n            '<div>Players can create clans in-game using the Battle.net clan interface.</div>' +\n          '</div>' +\n        '</td></tr>';\n        return;\n      }\n      tbody.innerHTML = clans.map(c => {\n        const cname = escapeHtml(c.name);\n        const ctag = escapeHtml(c.tag);\n        return '<tr>' +\n          '<td style=\"font-family:monospace;font-weight:700\">#' + c.cid + '</td>' +\n          '<td><span class=\"badge badge-admin\">[' + ctag + ']</span></td>' +\n          '<td style=\"font-weight:700;color:#fff\">' + cname + '</td>' +\n          '<td style=\"color:var(--color-frost)\">👑 ' + escapeHtml(c.chieftain || 'Vacant') + '</td>' +\n          '<td style=\"font-family:monospace\">' + (c.member_count || 1) + ' members</td>' +\n          '<td style=\"font-size:.8rem;color:var(--color-ink-2)\">' + (c.created_at ? c.created_at.slice(0,10) : '--') + '</td>' +\n          '<td>' +\n            '<div class=\"action-btns\">' +\n              '<button class=\"action-btn btn-primary\" onclick=\"viewClanRoster(' + c.cid + ', this.dataset.cname, this.dataset.ctag)\" data-cname=\"' + cname + '\" data-ctag=\"' + ctag + '\">👥 Roster</button>' +\n              '<button class=\"action-btn btn-danger\" onclick=\"disbandClan(' + c.cid + ', this.dataset.cname)\" data-cname=\"' + cname + '\">🗑️ Disband</button>' +\n            '</div>' +\n          '</td>' +\n        '</tr>';\n      }).join('');\n    }\n  } catch(e) {\n    console.error('Failed to load clans:', e);\n  }\n}\n\n\nlet currentRosterCid = null;\nlet currentRosterName = '';\nlet currentRosterTag = '';\n\nasync function viewClanRoster(cid, cname, tag) {\n  currentRosterCid = cid;\n  currentRosterName = cname;\n  currentRosterTag = tag;\n  document.getElementById('rosterClanName').textContent = cname;\n  document.getElementById('rosterClanTag').textContent = '[' + tag + ']';\n  document.getElementById('rosterModal').style.display = 'flex';\n  loadRosterMembers(cid);\n}\n\nfunction closeRosterModal() {\n  document.getElementById('rosterModal').style.display = 'none';\n  currentRosterCid = null;\n}\n\nasync function loadRosterMembers(cid) {\n  const tbody = document.getElementById('rosterTbody');\n  tbody.innerHTML = '<tr><td colspan=\"6\" style=\"text-align:center;padding:2rem;color:var(--color-ink-2)\">Loading members...</td></tr>';\n  try {\n    const res = await fetch('/api/admin/clans/' + cid + '/members');\n    const d = await res.json();\n    if (d.success) {\n      const members = d.members || [];\n      if (members.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"6\" style=\"text-align:center;padding:2rem;color:var(--color-ink-2)\">No members found in clan</td></tr>';\n        return;\n      }\n      tbody.innerHTML = members.map(m => {\n        const isChieftain = m.status === 4;\n        let rankBadge = '<span class=\"badge badge-user\">⛏️ Peon</span>';\n        if (m.status === 4) rankBadge = '<span class=\"badge badge-gold\">👑 Chieftain</span>';\n        else if (m.status === 3) rankBadge = '<span class=\"badge badge-silver\">🔮 Shaman</span>';\n        else if (m.status === 2) rankBadge = '<span class=\"badge badge-op\">⚔️ Grunt</span>';\n\n        const uname = escapeHtml(m.username);\n        const actionHtml = isChieftain ?\n          '<span style=\"font-size:.78rem;color:var(--color-frost);font-weight:600\">Leader</span>' :\n          '<button class=\"action-btn btn-warning\" onclick=\"promoteChieftain(' + cid + ', ' + m.uid + ', this.dataset.uname)\" data-uname=\"' + uname + '\">👑 Make Chieftain</button>';\n\n        return '<tr>' +\n          '<td style=\"font-family:monospace;font-weight:700;color:var(--color-ink-2)\">#' + m.uid + '</td>' +\n          '<td style=\"font-weight:700;color:#fff\">' + uname + '</td>' +\n          '<td>' + rankBadge + '</td>' +\n          '<td style=\"font-size:.78rem;color:var(--color-ink-2)\">' + (m.joined_at ? m.joined_at.slice(0, 10) : '--') + '</td>' +\n          '<td style=\"font-size:.78rem;color:var(--color-ink-2)\">' + (m.last_login ? m.last_login.slice(0, 10) : 'Never') + '</td>' +\n          '<td>' + actionHtml + '</td>' +\n        '</tr>';\n      }).join('');\n    } else {\n      tbody.innerHTML = '<tr><td colspan=\"6\" style=\"text-align:center;color:#ef4444;padding:2rem\">' + escapeHtml(d.error || 'Failed to load members') + '</td></tr>';\n    }\n  } catch(e) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" style=\"text-align:center;color:#ef4444;padding:2rem\">Error: ' + escapeHtml(e.message) + '</td></tr>';\n  }\n}\n\nasync function promoteChieftain(cid, uid, uname) {\n  if (!confirm('Promote \"' + uname + '\" to Chieftain of ' + currentRosterName + '? Current chieftain will become Shaman.')) return;\n  try {\n    const res = await fetch('/api/admin/clans/' + cid + '/chieftain', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ uid })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(uname + ' is now Clan Chieftain!');\n      loadRosterMembers(cid);\n      loadClans();\n    } else {\n      showToast(d.error || 'Failed to promote chieftain', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\nasync function disbandClan(cid, name) {\n  if (!confirm('Are you sure you want to permanently disband clan \"' + name + '\" (# ' + cid + ')?')) return;\n  try {\n    const res = await fetch('/api/admin/clans/' + cid, { method: 'DELETE' });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast('Clan #' + cid + ' disbanded successfully!');\n      loadClans();\n    } else {\n      showToast(d.error || 'Failed to disband clan', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\n// -----------------------------\n// TAB 6: IP Bans & Security\n// -----------------------------\nasync function loadBans() {\n  try {\n    const res = await fetch('/api/admin/bans');\n    const d = await res.json();\n    if (d.success) {\n      allBans = d.bans || [];\n      document.getElementById('tabBadgeBans').textContent = allBans.length;\n      renderBans(allBans);\n    }\n  } catch(e) {\n    console.error('Failed to load bans:', e);\n  }\n}\n\nfunction renderBans(bans) {\n  const tbody = document.getElementById('bansTbody');\n  if (bans.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"6\">' +\n      '<div class=\"empty-state\">' +\n        '<div class=\"empty-icon\">🛡️</div>' +\n        '<div style=\"font-weight:700;color:#fff;font-size:1rem;margin-bottom:.35rem\">No Active Bans</div>' +\n        '<div>Your server connection blacklist and database bans are currently clean.</div>' +\n      '</div>' +\n    '</td></tr>';\n    return;\n  }\n  tbody.innerHTML = bans.map(b => {\n    const bip = escapeHtml(b.ip || 'N/A');\n    const buser = escapeHtml(b.username || 'N/A');\n    const bby = escapeHtml(b.banned_by || 'Admin');\n    const breason = escapeHtml(b.reason || 'Banned');\n    const bdate = b.banned_at ? new Date(b.banned_at).toLocaleString() : '--';\n    const bexpires = b.expires_at ? new Date(b.expires_at).toLocaleString() : '<span style=\"color:#10b981;font-weight:600\">Permanent</span>';\n    const bid = b.id || '';\n    return '<tr>' +\n      '<td style=\"font-weight:700;color:#fff\">' + (buser !== 'N/A' && buser !== '(unspecified)' ? '👤 ' + buser : '<span style=\"color:var(--color-ink-2)\">--</span>') + '</td>' +\n      '<td style=\"font-family:monospace;font-weight:700;color:#FCA5A5\">' + (bip !== 'N/A' ? '🚫 ' + bip : '<span style=\"color:var(--color-ink-2)\">N/A</span>') + '</td>' +\n      '<td style=\"color:var(--color-ink-2)\">' + bby + '</td>' +\n      '<td style=\"color:var(--color-ink-2)\">' + breason + '</td>' +\n      '<td style=\"color:var(--color-ink-2);font-size:0.8rem\">' + bdate + '</td>' +\n      '<td style=\"color:var(--color-ink-2);font-size:0.8rem\">' + bexpires + '</td>' +\n      '<td>' +\n        '<button class=\"action-btn btn-success\" onclick=\"unbanIp(this.dataset.ip, this.dataset.user, this.dataset.id)\" data-ip=\"' + bip + '\" data-user=\"' + buser + '\" data-id=\"' + bid + '\">🔓 Unban</button>' +\n      '</td>' +\n    '</tr>';\n  }).join('');\n}\n\nfunction openBanModal() { document.getElementById('banModal').style.display = 'flex'; }\nfunction closeBanModal() { document.getElementById('banModal').style.display = 'none'; }\n\ndocument.getElementById('banForm').onsubmit = async (e) => {\n  e.preventDefault();\n  const username = document.getElementById('banUserInput') ? document.getElementById('banUserInput').value.trim() : '';\n  const ip = document.getElementById('banIpInput').value.trim();\n  const reason = document.getElementById('banReasonInput').value.trim();\n  const duration = document.getElementById('banDurationInput') ? document.getElementById('banDurationInput').value : '0';\n  if (!username && !ip) {\n    showToast('Please provide a Username or IP Address', true);\n    return;\n  }\n  try {\n    const res = await fetch('/api/admin/bans/add', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ username, ip, reason, duration })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Ban applied!');\n      closeBanModal();\n      document.getElementById('banForm').reset();\n      loadBans();\n      loadAccounts();\n    } else {\n      showToast(d.error || 'Failed to apply ban', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n};\n\nasync function unbanIp(ip, username, id) {\n  const targetLabel = (username && username !== 'N/A' && username !== '(unspecified)') ? username : ip;\n  if (!confirm('Unban ' + targetLabel + '?')) return;\n  try {\n    const res = await fetch('/api/admin/bans/remove', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ ip, username, id })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Ban removed!');\n      loadBans();\n      loadAccounts();\n    } else {\n      showToast(d.error || 'Failed to unban', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\n// -----------------------------\n// TAB 7: Announcements & MOTD\n// -----------------------------\nasync function loadAnnouncements() {\n  try {\n    const res = await fetch('/api/admin/announcements');\n    const d = await res.json();\n    if (d.success) {\n      document.getElementById('editW3Motd').value = d.w3motd || '';\n      document.getElementById('editBnMotd').value = d.bnmotd || '';\n      document.getElementById('editNews').value = d.news || '';\n      document.getElementById('editTopics').value = d.topics || '';\n      showToast('Announcements loaded from server!');\n    }\n  } catch(e) {\n    showToast('Failed to load announcements: ' + e.message, true);\n  }\n}\n\nasync function saveAnnouncements() {\n  const w3motd = document.getElementById('editW3Motd').value;\n  const bnmotd = document.getElementById('editBnMotd').value;\n  const news = document.getElementById('editNews').value;\n  const topics = document.getElementById('editTopics').value;\n  try {\n    showToast('Saving announcements...');\n    const res = await fetch('/api/admin/announcements', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ w3motd, bnmotd, news, topics, reloadServer: true })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast('Announcements saved and applied to PvPGN!');\n    } else {\n      showToast(d.error || 'Failed to save', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\n// -----------------------------\n// TAB 9: Logs\n// -----------------------------\nasync function loadLogs() {\n  try {\n    const res = await fetch('/api/admin/logs');\n    const d = await res.json();\n    if (d.success) {\n      allLogs = d.logs || [];\n      filterLogs();\n    }\n  } catch(e) {\n    document.getElementById('logViewer').textContent = 'Error loading logs: ' + e.message;\n  }\n}\n\nfunction filterLogs() {\n  const viewer = document.getElementById('logViewer');\n  const q = document.getElementById('logSearch').value.toLowerCase().trim();\n  let lines = allLogs;\n\n  if (currentLogFilter === 'info') lines = lines.filter(l => l.includes('[info]'));\n  else if (currentLogFilter === 'warn') lines = lines.filter(l => l.includes('[warn]'));\n  else if (currentLogFilter === 'error') lines = lines.filter(l => l.includes('[error]'));\n\n  if (q) lines = lines.filter(l => l.toLowerCase().includes(q));\n\n  if (lines.length === 0) {\n    viewer.innerHTML = '<div style=\"color:var(--color-ink-2);text-align:center;padding:2rem\">No log entries matching filter</div>';\n    return;\n  }\n\n  viewer.innerHTML = lines.map(line => {\n    let cls = 'log-line';\n    if (line.includes('[error]')) cls += ' log-err';\n    else if (line.includes('[warn]')) cls += ' log-warn';\n    else if (line.includes('[info]')) cls += ' log-info';\n    return '<div class=\"' + cls + '\">' + escapeHtml(line) + '</div>';\n  }).join('');\n\n  viewer.scrollTop = viewer.scrollHeight;\n}\n\nfunction copyLogs() {\n  const text = allLogs.join('\\n');\n  navigator.clipboard.writeText(text).then(() => {\n    showToast('Logs copied to clipboard (' + allLogs.length + ' lines)!');\n  });\n}\n\n// -----------------------------\n// TAB 10: Container Stats & DB Stats\n// -----------------------------\nasync function loadContainers() {\n  try {\n    const [cRes, sRes] = await Promise.all([\n      fetch('/api/admin/containers'),\n      fetch('/api/admin/containers/stats')\n    ]);\n    const cData = await cRes.json();\n    const sData = await sRes.json();\n\n    const tbody = document.getElementById('containersTbody');\n    if (cData.success && cData.containers && cData.containers.length > 0) {\n      const statsMap = {};\n      if (sData.success && sData.stats) {\n        sData.stats.forEach(st => statsMap[st.name] = st);\n      }\n\n      tbody.innerHTML = cData.containers.map(c => {\n        const isUp = c.state === 'running';\n        const stBadge = isUp ? '<span class=\"badge badge-active\">RUNNING</span>' : '<span class=\"badge badge-locked\">STOPPED</span>';\n        const st = statsMap[c.name] || { cpuPerc: 0, memUsedMb: 0, memLimitMb: 0, memPerc: 0 };\n\n        const cpuFillClass = st.cpuPerc > 70 ? 'fill-danger' : (st.cpuPerc > 30 ? 'fill-warn' : '');\n        const memFillClass = st.memPerc > 80 ? 'fill-danger' : (st.memPerc > 50 ? 'fill-warn' : '');\n\n        return '<tr>' +\n          '<td style=\"font-weight:700;color:#fff\">' + escapeHtml(c.name) + '</td>' +\n          '<td>' + stBadge + '</td>' +\n          '<td>' +\n            '<div class=\"progress-wrap\"><div class=\"progress-fill ' + cpuFillClass + '\" style=\"width:' + Math.min(100, st.cpuPerc) + '%\"></div></div>' +\n            '<span style=\"font-family:monospace;font-size:.8rem;color:var(--color-frost)\">' + st.cpuPerc + '%</span>' +\n          '</td>' +\n          '<td>' +\n            '<div class=\"progress-wrap\"><div class=\"progress-fill ' + memFillClass + '\" style=\"width:' + Math.min(100, st.memPerc) + '%\"></div></div>' +\n            '<span style=\"font-family:monospace;font-size:.8rem\">' + st.memUsedMb + ' / ' + st.memLimitMb + ' MB (' + st.memPerc + '%)</span>' +\n          '</td>' +\n          '<td style=\"font-family:monospace;font-size:.78rem;color:var(--color-ink-2)\">' + escapeHtml(c.ports || '--') + '</td>' +\n        '</tr>';\n      }).join('');\n    }\n  } catch(e) {\n    console.error('Failed to load container stats:', e);\n  }\n}\n\nasync function loadDbStats() {\n  try {\n    const res = await fetch('/api/admin/db-stats');\n    const d = await res.json();\n    const tbody = document.getElementById('dbTablesTbody');\n    if (d.success && d.tables) {\n      tbody.innerHTML = d.tables.map(t => '<tr>' +\n        '<td style=\"font-family:monospace;font-weight:700;color:#fff\">' + escapeHtml(t.name) + '</td>' +\n        '<td style=\"font-family:monospace\">' + (t.rowsCount != null ? Number(t.rowsCount).toLocaleString() : '--') + '</td>' +\n        '<td style=\"font-family:monospace;color:var(--color-frost)\">' + (t.sizeKb != null ? t.sizeKb + ' KB' : '--') + '</td>' +\n        '<td style=\"color:var(--color-ink-2);font-size:.8rem\">' + (t.name === 'pvpgn_chat_logs' ? '💬 Realm Chat Audit Logs' : (t.name === 'pvpgn_chat_mutes' ? '🔇 Active Chat Mutes' : (t.name.startsWith('pvpgn') ? 'PvPGN Core Storage' : 'Web & Auth Table'))) + '</td>' +\n      '</tr>').join('');\n    }\n  } catch(e) {\n    console.error('Failed to load DB stats:', e);\n  }\n}\n\n// -----------------------------\n// Modals & General Actions\n// -----------------------------\nfunction escapeHtml(s) {\n  if (!s) return '';\n  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#039;');\n}\n\nfunction openCreateModal() { document.getElementById('createModal').style.display = 'flex'; }\nfunction closeCreateModal() { document.getElementById('createModal').style.display = 'none'; }\nfunction openPassModal(uid, name) {\n  document.getElementById('passUid').value = uid;\n  document.getElementById('passUsername').textContent = name;\n  document.getElementById('passInput').value = '';\n  document.getElementById('passModal').style.display = 'flex';\n}\nfunction closePassModal() { document.getElementById('passModal').style.display = 'none'; }\n\ndocument.getElementById('createForm').onsubmit = async (e) => {\n  e.preventDefault();\n  const username = document.getElementById('newUsername').value.trim();\n  const password = document.getElementById('newPassword').value;\n  const email = document.getElementById('newEmail').value.trim();\n  const role = document.getElementById('newRole').value;\n  try {\n    const res = await fetch('/api/admin/accounts/create', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ username, password, email, role })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Account created!');\n      closeCreateModal();\n      document.getElementById('createForm').reset();\n      loadAccounts();\n    } else {\n      showToast(d.error || 'Failed to create', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n};\n\ndocument.getElementById('passForm').onsubmit = async (e) => {\n  e.preventDefault();\n  const uid = document.getElementById('passUid').value;\n  const password = document.getElementById('passInput').value;\n  try {\n    const res = await fetch('/api/admin/accounts/password', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ uid, password })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast('Password updated!');\n      closePassModal();\n    } else {\n      showToast(d.error || 'Failed to update password', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n};\n\nasync function toggleRole(uid, role) {\n  try {\n    const res = await fetch('/api/admin/accounts/role', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ uid, role })\n    });\n    if (res.ok) {\n      showToast('Role updated to ' + role + '!');\n      loadAccounts();\n    } else {\n      const d = await res.json();\n      showToast(d.error || 'Failed to update role', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\nasync function toggleLock(uid, lock) {\n  try {\n    const res = await fetch('/api/admin/accounts/lock', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({ uid, lock })\n    });\n    if (res.ok) {\n      showToast(lock ? 'Account locked!' : 'Account unlocked!');\n      loadAccounts();\n    } else {\n      const d = await res.json();\n      showToast(d.error || 'Failed to update lock', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\nasync function deleteAccount(uid, name) {\n  if (!confirm('Are you sure you want to permanently delete account \"' + name + '\"?')) return;\n  try {\n    const res = await fetch('/api/admin/accounts/' + uid, { method: 'DELETE' });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast('Account deleted!');\n      loadAccounts();\n    } else {\n      showToast(d.error || 'Failed to delete', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\nasync function restartServer() {\n  if (!confirm('Restart PvPGN server daemon? Existing in-game connections will briefly drop.')) return;\n  try {\n    showToast('Reloading PvPGN server daemon...');\n    const res = await fetch('/api/admin/server/restart', { method: 'POST' });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast('PvPGN server reloaded successfully!');\n      refreshAll();\n    } else {\n      showToast(d.error || 'Failed to restart server', true);\n    }\n  } catch(e) {\n    showToast(e.message, true);\n  }\n}\n\nfunction refreshAll() {\n  loadAccounts();\n  loadOverview();\n  const activeTab = document.querySelector('.tab-content.active');\n  if (activeTab) {\n    if (activeTab.id === 'ladderTab') loadLadder();\n    if (activeTab.id === 'clansTab') loadClans();\n    if (activeTab.id === 'bansTab') loadBans();\n    if (activeTab.id === 'announcementsTab') loadAnnouncements();\n    if (activeTab.id === 'logsTab') loadLogs();\n    if (activeTab.id === 'systemTab') { loadContainers(); loadDbStats(); }\n    if (activeTab.id === 'chatTab') { loadChatMutes(); loadChatLogs(); }\n  }\n}\n\n\n// -----------------------------\n// TAB: Realm Chat & Moderation (Dialog & Stream)\n// -----------------------------\nlet chatSearchTimeout = null;\nlet autoScrollEnabled = true;\nlet currentSourceFilter = 'all';\nlet allLoadedChatLogs = [];\n\nfunction toggleAutoScroll() {\n  autoScrollEnabled = !autoScrollEnabled;\n  const btn = document.getElementById('autoScrollToggleBtn');\n  if (btn) btn.textContent = autoScrollEnabled ? '⬇️ Auto-scroll: ON' : '⏸️ Auto-scroll: PAUSED';\n}\n\nfunction toggleMutesList() {\n  const wrap = document.getElementById('mutesListWrap');\n  const btn = document.getElementById('toggleMutesBtn');\n  if (wrap.style.display === 'none') {\n    wrap.style.display = 'block';\n    btn.textContent = '✕ Hide Details';\n    loadChatMutes();\n  } else {\n    wrap.style.display = 'none';\n    btn.textContent = '👁️ View Mute Details';\n  }\n}\n\nfunction setSourceFilter(src) {\n  currentSourceFilter = src;\n  document.querySelectorAll('.filter-tab[data-source-filter]').forEach(b => {\n    b.classList.toggle('active', b.getAttribute('data-source-filter') === src);\n  });\n  renderChatStream();\n}\n\nfunction onChannelFilterChange() {\n  loadChatLogs();\n}\n\nfunction debounceChatSearch() {\n  clearTimeout(chatSearchTimeout);\n  chatSearchTimeout = setTimeout(() => {\n    renderChatStream();\n  }, 250);\n}\n\nasync function loadChatChannels() {\n  try {\n    const res = await fetch('/api/admin/chat/channels');\n    const d = await res.json();\n    if (d.success && d.channels) {\n      const select = document.getElementById('chatChannelFilter');\n      if (!select) return;\n      const current = select.value;\n      const defaults = ['all', 'DotA and Friends', 'The Void', 'Warcraft III', 'USA'];\n      const combined = Array.from(new Set([...defaults, ...d.channels]));\n      select.innerHTML = combined.map(c => {\n        if (c === 'all') return '<option value=\"all\">🌟 All Channels (Global Stream)</option>';\n        return '<option value=\"' + escapeHtml(c) + '\">' + escapeHtml(c) + '</option>';\n      }).join('');\n      select.value = current;\n    }\n  } catch(e) {\n    console.error('Failed to load channels:', e);\n  }\n}\n\nasync function loadChatLogs() {\n  const channelSelect = document.getElementById('chatChannelFilter');\n  const selectedChannel = channelSelect ? channelSelect.value : 'all';\n  const box = document.getElementById('chatStreamBox');\n  try {\n    let url = '/api/admin/chat/logs?limit=200';\n    if (selectedChannel && selectedChannel !== 'all') {\n      url += '&channel=' + encodeURIComponent(selectedChannel);\n    }\n    const res = await fetch(url);\n    const d = await res.json();\n    if (d.success && d.logs) {\n      allLoadedChatLogs = (d.logs || []).reverse(); // oldest first for live stream\n      renderChatStream();\n    }\n  } catch (err) {\n    console.error('Failed to load chat logs:', err);\n  }\n}\n\nfunction renderChatStream() {\n  const box = document.getElementById('chatStreamBox');\n  if (!box) return;\n\n  const searchInput = document.getElementById('chatSearchInput');\n  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';\n\n  let list = allLoadedChatLogs;\n\n  if (currentSourceFilter !== 'all') {\n    list = list.filter(l => l.source === currentSourceFilter);\n  }\n\n  if (query) {\n    list = list.filter(l =>\n      (l.username && l.username.toLowerCase().includes(query)) ||\n      (l.message && l.message.toLowerCase().includes(query)) ||\n      (l.channel && l.channel.toLowerCase().includes(query))\n    );\n  }\n\n  if (list.length === 0) {\n    box.innerHTML = '<div style=\"color:var(--color-ink-2);text-align:center;padding:3rem\">No chat messages found</div>';\n    return;\n  }\n\n  box.innerHTML = list.map(log => {\n    const isWeb = log.source === 'web';\n    const sourceBadge = isWeb\n      ? '<span class=\"chat-badge-source chat-source-web\">🌐 WEB</span>'\n      : '<span class=\"chat-badge-source chat-source-bnet\">⚔️ BNET</span>';\n    const safeUser = escapeHtml(log.username || 'Unknown');\n    const safeChannel = escapeHtml(log.channel || 'DotA and Friends');\n    const safeMsg = escapeHtml(log.message || '');\n    const timeStr = log.created_at ? new Date(log.created_at).toLocaleTimeString() : '--';\n\n    return '<div class=\"chat-line\">' +\n      '<span class=\"chat-time\">' + timeStr + '</span>' +\n      '<span class=\"chat-badge-channel\">' + safeChannel + '</span>' +\n      sourceBadge +\n      '<span class=\"chat-user\" data-user=\"' + safeUser + '\" onclick=\"openMuteModal(this.dataset.user)\" title=\"Click to mute player\">' + safeUser + ':</span>' +\n      '<span class=\"chat-msg-text\">' + safeMsg + '</span>' +\n      '<button class=\"chat-quick-mute\" data-user=\"' + safeUser + '\" onclick=\"openMuteModal(this.dataset.user)\" title=\"Mute ' + safeUser + '\">🔇</button>' +\n    '</div>';\n  }).join('');\n\n  if (autoScrollEnabled) {\n    box.scrollTop = box.scrollHeight;\n  }\n}\n\nasync function sendAdminChatMessage(e) {\n  e.preventDefault();\n  const input = document.getElementById('adminMsgInput');\n  const msg = input.value.trim();\n  if (!msg) return;\n\n  const channelSelect = document.getElementById('chatChannelFilter');\n  const channel = (channelSelect && channelSelect.value !== 'all') ? channelSelect.value : 'DotA and Friends';\n\n  try {\n    const res = await fetch('/api/realm-chat/send', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        username: 'Admin',\n        message: msg,\n        channel: channel\n      })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      input.value = '';\n      loadChatLogs();\n    } else {\n      showToast(d.error || 'Failed to send message', true);\n    }\n  } catch(err) {\n    showToast(err.message, true);\n  }\n}\n\nasync function loadChatMutes() {\n  const tbody = document.getElementById('mutesTbody');\n  try {\n    const res = await fetch('/api/admin/chat/mutes');\n    const d = await res.json();\n    if (d.success && d.mutes) {\n      const activeMutes = d.mutes.filter(m => m.is_active);\n      const badgeElem = document.getElementById('activeMutesCountBadge');\n      if (badgeElem) badgeElem.textContent = activeMutes.length + ' Active';\n      const tabBadge = document.getElementById('tabBadgeMutes');\n      if (tabBadge) tabBadge.textContent = activeMutes.length;\n\n      if (d.mutes.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"7\" style=\"text-align:center;padding:1.5rem;color:var(--color-ink-2)\">No muted players found</td></tr>';\n        return;\n      }\n      tbody.innerHTML = d.mutes.map(m => {\n        const isActive = !!m.is_active;\n        const statusBadge = isActive ? '<span class=\"badge badge-locked\">🔴 Active</span>' : '<span class=\"badge badge-user\">⚪ Expired</span>';\n        const expiresStr = m.expires_at ? new Date(m.expires_at).toLocaleString() : '<span style=\"color:#ef4444;font-weight:700\">Permanent</span>';\n        const safeUser = escapeHtml(m.username);\n        const safeReason = escapeHtml(m.reason || 'Rule violation');\n        const safeAdmin = escapeHtml(m.muted_by || 'Admin');\n        return '<tr>' +\n          '<td style=\"font-family:monospace;color:var(--color-ink-2)\">#' + m.id + '</td>' +\n          '<td style=\"font-weight:700;color:#fff\">' + safeUser + '</td>' +\n          '<td>' + safeReason + '</td>' +\n          '<td style=\"color:var(--color-ink-2)\">' + safeAdmin + '</td>' +\n          '<td style=\"font-family:monospace;font-size:.8rem\">' + expiresStr + '</td>' +\n          '<td>' + statusBadge + '</td>' +\n          '<td>' +\n            (isActive ? '<button class=\"action-btn btn-success\" data-user=\"' + safeUser + '\" onclick=\"unmutePlayer(this.dataset.user)\">🔊 Unmute</button>' : '<span style=\"color:var(--color-ink-2);font-size:.78rem\">--</span>') +\n          '</td>' +\n        '</tr>';\n      }).join('');\n    }\n  } catch (err) {\n    console.error('Failed to load mutes:', err);\n  }\n}\n\nfunction openMuteModal(optUsername) {\n  document.getElementById('muteUsernameInput').value = optUsername || '';\n  document.getElementById('muteReasonInput').value = '';\n  document.getElementById('muteModal').style.display = 'flex';\n}\nfunction closeMuteModal() {\n  document.getElementById('muteModal').style.display = 'none';\n}\n\nfunction openPurgeModal() {\n  document.getElementById('purgeModal').style.display = 'flex';\n}\nfunction closePurgeModal() {\n  document.getElementById('purgeModal').style.display = 'none';\n}\n\nasync function unmutePlayer(username) {\n  if (!confirm('Unmute player \"' + username + '\"?')) return;\n  try {\n    const res = await fetch('/api/admin/chat/unmute', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ username })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Player unmuted');\n      loadChatMutes();\n    } else {\n      showToast(d.error || 'Failed to unmute', true);\n    }\n  } catch (err) {\n    showToast(err.message, true);\n  }\n}\n\ndocument.getElementById('muteForm').onsubmit = async (e) => {\n  e.preventDefault();\n  const username = document.getElementById('muteUsernameInput').value.trim();\n  const minutes = parseInt(document.getElementById('muteDurationSelect').value, 10);\n  const reason = document.getElementById('muteReasonInput').value.trim();\n  try {\n    const res = await fetch('/api/admin/chat/mute', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ username, minutes, reason })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Player muted successfully');\n      closeMuteModal();\n      loadChatMutes();\n    } else {\n      showToast(d.error || 'Failed to mute', true);\n    }\n  } catch (err) {\n    showToast(err.message, true);\n  }\n};\n\ndocument.getElementById('purgeForm').onsubmit = async (e) => {\n  e.preventDefault();\n  const range = document.getElementById('purgeRangeSelect').value;\n  try {\n    const res = await fetch('/api/admin/chat/logs/purge', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ range })\n    });\n    const d = await res.json();\n    if (res.ok && d.success) {\n      showToast(d.message || 'Purged chat logs');\n      closePurgeModal();\n      loadChatLogs();\n      loadDbStats();\n    } else {\n      showToast(d.error || 'Failed to purge', true);\n    }\n  } catch (err) {\n    showToast(err.message, true);\n  }\n};\n\nwindow.onload = () => {\n  loadAccounts();\n  loadOverview();\n  setInterval(() => {\n    const activeTab = document.querySelector('.tab-content.active');\n    if (activeTab && activeTab.id === 'gamesTab') loadOverview();\n    if (activeTab && activeTab.id === 'logsTab') loadLogs();\n    if (activeTab && activeTab.id === 'systemTab') loadContainers();\n    if (activeTab && activeTab.id === 'chatTab') loadChatLogs();\n  }, 5000);\n};\n</script>\n</body>\n</html>";
}
